from wslib import *

# roles: ctx (context), prem (reason), evid (evidence/example), analogy (comparison),
#        counter (opposing view), ic (intermediate conclusion), conc (main conclusion)

QUESTIONS = [
dict(n=1, orig=1, answer='A', type='Main conclusion',
     passage=[('ctx', 'It may seem like we’re living in the age of the conspiracy theory, but ‘alternative facts’ have been around since long before conspiracy theorists claimed the 1969 moon landing was faked by a movie production crew.'),
              ('conc', 'The truth is that society could be much smarter in how it addresses the popularity of such theories.'),
              ('ic', 'While it may sound counter-intuitive, it’s actually not all that useful to directly challenge someone’s belief in a conspiracy theory.'),
              ('prem', 'That sort of intervention just tends to reinforce existing beliefs. More effective strategies focus on how information is delivered by scientists and other authorities and on developing open communication between the public and those providing ‘official’ or ‘expert’ information.'),
              ('ic', 'Finally, it’s critical not to simply dismiss conspiracy theories as trivial nonsense,'),
              ('prem', 'as they can reveal much about levels of trust, equality, and other key components of a functioning society.')],
     stem='Which one of the following best expresses the main conclusion of the above argument?',
     options={'A': 'Society could be much smarter in how it addresses the popularity of conspiracy theories.',
              'B': 'It’s not all that useful to directly challenge someone’s belief in a conspiracy theory.',
              'C': 'Challenging someone’s belief in a conspiracy theory just tends to reinforce it.',
              'D': 'Better strategies for dealing with conspiracy theories focus on authorities’ information delivery and communication with the public.',
              'E': 'It’s critical not to simply dismiss conspiracy theories as trivial nonsense.'},
     right='“The truth is…” is the big claim. Everything after it lists ways society could be smarter: don’t challenge directly, deliver information better, don’t dismiss.',
     why={'B': 'One of the ways society could be smarter, backed by its own reason. An intermediate conclusion.',
          'C': 'The reason for B, so it sits even further down the argument.',
          'D': 'Another of the supporting points, not the overall claim.',
          'E': 'The last supporting point (“Finally”), with its own “as…” reason.'},
     gap='“The truth is that…” flags the claim. “Finally” tells you the rest is a list of points backing it up.'),

dict(n=2, orig=3, answer='E', type='Principle',
     passage=[('ctx', 'Religious believers often try to convince others to act morally by offering the reward of some kind of ‘heaven’.'),
              ('conc', 'But this approach misunderstands the nature of morality.'),
              ('prem', 'We should do the right thing because it is the right thing, not because of selfish desires about the consequences. Ethics is a matter of virtuous character, not seeking rewards and avoiding punishments.'),
              ('evid', 'For instance, if you believe it is right to pray daily then you should do so even if it will not get you into heaven.')],
     stem='Which one of the following best illustrates the principle used in the above argument?',
     options={'A': 'You should not jump queues even if you are in a rush to get somewhere.',
              'B': 'You should be honest about your friend’s new outfit even if you might offend them.',
              'C': 'You should not steal from an organisation even if you believe that it is corrupt.',
              'D': 'You should not give to charity just to avoid feeling guilty.',
              'E': 'You should return lost property even if the owner is not offering any compensation.'},
     right='Returning lost property is the right thing, so do it even with no reward on offer. Just like praying even if it won’t get you into heaven.',
     why={'A': 'About resisting a temptation when you are in a hurry. No reward for doing right is involved.',
          'B': 'A clash between honesty and hurting a friend. The worry is a cost to them, not a reward for you.',
          'C': 'About whether the victim’s wrongdoing excuses you. Rewards play no part.',
          'D': 'Tells you <b>not</b> to do a good act. The principle says do the right thing anyway, whatever the payoff.'},
     working_title='Working: write the principle first',
     working=f"""<p class="skel">Heaven as a reward {ar('pen')} wrong reason to be moral {ar('pen')} pray if it is right, even if it won’t get you into heaven.<br>
So the principle: <b>do the right thing because it is right, even when there is no reward for you</b>.</p>
<div class="map">
<div><b>E</b><span>Returning lost property is right → do it even with no compensation (no reward). {tick()} Same principle, new setting.</span></div>
<div><b>A</b><span>Don’t jump the queue even in a rush: about inconvenience, not reward. {cross()}</span></div>
<div><b>B</b><span>Be honest even if it offends: a cost to someone else. {cross()}</span></div>
<div><b>C</b><span>Don’t steal even from a corrupt firm: about excuses, not reward. {cross()}</span></div>
<div><b>D</b><span>Don’t give to charity to dodge guilt: stops a good act instead of doing it for no reward. {cross()}</span></div>
</div>
{note('The example in the passage is the template: “do the right thing even if it will not get you [a reward]”. E copies it.', 'tip')}"""),

dict(n=3, orig=4, answer='E', type='Assumption',
     passage=[('ctx', 'When we are walking our centre of mass is constantly moving up and down. If we are wearing a backpack then this also moves up and down as we walk. A new prototype has been developed in which the backpack is suspended on sliding rails that allow it to move more smoothly.'),
              ('prem', 'It is attached to a pair of rubber ropes on a pulley system'),
              ('analogy', 'which acts like a car’s suspension'),
              ('prem', 'to reduce the impact of the pack as you walk, making it easier to carry. Additionally, the relative movement between the pack and the body is used to power a small generator that converts the mechanical power into electricity.'),
              ('counter', 'Although these features will increase the price of the product,'),
              ('conc', 'this backpack is likely to become one of the most popular on the market.')],
     stem='Which one of the following is an underlying assumption of the above argument?',
     options={'A': 'Cars that have better suspension systems tend to be more popular than other models.',
              'B': 'People carrying this new type of backpack will be able to use the electricity as it is generated.',
              'C': 'The most important feature of a backpack is the ease with which it can be carried.',
              'D': 'Current devices that can generate electricity as you walk do not create as much electricity as the new backpack will.',
              'E': 'Consumers will consider the benefits of the new backpack design to be worth the increase in price.'},
     right='The price goes up, yet it will be popular. That only works if buyers think the comfort and the electricity are worth paying extra for.',
     why={'A': 'The car is just a comparison to explain the suspension. Car sales are irrelevant.',
          'B': 'Not needed. The power could be stored for later, and comfort alone could sell it.',
          'C': 'Too strong. Ease of carrying need not be the <b>most</b> important feature for it to sell well.',
          'D': 'Not needed. No comparison with other devices is made.'},
     gap='Negation test: if buyers think the benefits are NOT worth the higher price, it won’t be popular. The argument falls.'),

dict(n=4, orig=5, answer='D', type='Weaken',
     passage=[('ic', 'Unfortunately, in recent years, teachers in the UK have ‘gone soft’ and no longer have the right priorities.'),
              ('prem', 'Most schools these days are concerned with children’s happiness, confidence and self-expression rather than maximising academic achievement.'),
              ('conc', 'We should reverse this trend and re-introduce more traditional teaching methods (such as those focused on memorisation) in all schools.'),
              ('prem', 'After all, the purpose of teaching is to develop children’s learning, and discipline and good exam results can get you into a top university and ensure a high-paying career later in life. Traditional methods are tried-and-tested,'),
              ('ic', 'so they are the best way of ensuring good academic outcomes for children.')],
     stem='Which one of the following, if true, most weakens the above argument?',
     options={'A': 'Some private schools have maintained a focus on traditional teaching methods despite changes in attitudes among education professionals.',
              'B': 'Traditional teaching methods involve the use of strict punishment in schools to improve discipline, which some parents dislike.',
              'C': 'Modern technology has increased the range of teaching methods available.',
              'D': 'Careers have changed significantly over time and now require a wider range of skills than those represented by academic achievement.',
              'E': 'As part of a pilot programme, some schools have started allowing students to opt out of homework in order to provide a better ‘work–life balance’.'},
     right='The argument says exam results “ensure a high-paying career”. If careers now need wider skills, results alone won’t do that, and confidence and self-expression may matter after all.',
     why={'A': 'Some schools keeping traditional methods says nothing about whether those methods work better.',
          'B': 'Some parents disliking punishment is a side issue. It doesn’t show the methods fail to raise results.',
          'C': 'More methods being available doesn’t show traditional ones are worse.',
          'E': 'If anything, another example of the ‘soft’ trend the author dislikes. No results are given.'},
     gap='Attack the link the argument leans on: good exam results → top university → high-paying career.'),

dict(n=5, orig=9, answer='E', type='Flaw',
     passage=[('counter', 'Researchers believe that shortened sleep, and shortened rapid eye movement (REM) sleep in particular, contributes to a shorter lifespan. For every 5% reduction in REM sleep, mortality rates increase by 13% to 17% among older and middle-aged adults, they report.'),
              ('ctx', 'But is there really a connection?'),
              ('evid', 'A study comparing the sleeping patterns of men and women from 28 different countries using fitness trackers has shown that Japan is the country that sleeps the least. Japanese men and women sleep only an average of 6 hours and 30 minutes, and 6 hours and 40 minutes, respectively. Yet Japanese women have a life expectancy of 87.3 years – the second highest in the world after Hong Kong – while male life expectancy in Japan is the third highest internationally.'),
              ('conc', 'What this shows is that shortened sleep does not, in fact, contribute to a shorter lifespan.')],
     stem='Which one of the following best illustrates the flaw in the above argument?',
     options={'A': 'Health problems that shorten people’s lifespans might also interfere with their sleep in old age.',
              'B': 'The proportion of sleep that is REM sleep might decrease with age.',
              'C': 'The length of time that the Japanese sleep might be gradually increasing.',
              'D': 'Japanese life expectancy might now be falling to a level closer to the global average.',
              'E': 'The life expectancy of Japanese people might be even longer if they slept for longer.'},
     right='Other things (diet, healthcare) may keep the Japanese long-lived. Short sleep could still be cutting their lives, just from a very high starting point.',
     why={'A': 'This would weaken the researchers’ claim, so it helps the author. It isn’t a flaw in the argument.',
          'B': 'REM changing with age doesn’t touch the Japan evidence.',
          'C': 'Even if sleep is creeping up, the Japanese sleep least now and still live long.',
          'D': 'Questions whether the data is up to date. The flaw is in the reasoning, not the figures.'},
     gap='One group doing well despite a risk factor doesn’t show the factor is harmless. Ask: would they do even better without it?'),

dict(n=6, orig=10, answer='C', type='Parallel reasoning',
     passage=[('prem', 'Every participant in the cross-country race received either a trophy for finishing in the top ten, or a medal for participating.'),
              ('evid', 'Amy finished in twelfth place,'),
              ('conc', 'which means she will have been awarded a medal for participating.')],
     stem='Which one of the following most closely parallels the reasoning used in the above argument?',
     options={'A': 'The school can take in one hundred more pupils next year if they build more classrooms. They have not received approval for the building work, so they will not be able to increase their pupil intake.',
              'B': 'The shopkeeper can keep her store open on the weekends if she hires people who can work weekend shifts. It is Sunday and the store is open, so she must have hired new employees.',
              'C': 'Whenever Cara and her family visit the zoo they have an ice cream at the outdoor café or – if it’s raining – visit the butterfly house. It wasn’t raining when they went yesterday, so they must have had an ice cream at the café.',
              'D': 'If fireworks continue to be sold illegally, hospitals can expect a spike in fire-related injuries during the holiday season. There was a decrease in hospital admissions due to such injuries this year, so the efforts to crack down on illegal fireworks must be succeeding.',
              'E': 'There is only enough space left in the moving van for an armchair or a side table. The armchair has some sentimental value to Peter, so the side table will be left behind.'},
     right='Same shape: every time it is one of two things, the condition for one fails (not raining / not top ten), so it must be the other.',
     why={'A': 'An “if” rule with the condition missing. No either/or.',
          'B': 'An “if” rule run backwards: the store is open, so she must have hired. No either/or.',
          'D': 'An “if” rule, then a jump to a cause (the crackdown). No either/or.',
          'E': 'Two options, but one is picked for a reason (sentimental value). Nothing is ruled out by a rule.'},
     working_title='Working: strip it to a skeleton',
     working=f"""<p class="skel">Original: every time, either <b>X</b> (trophy, if top ten) or <b>Y</b> (medal) {ar('pen')} the condition for X fails (twelfth) {ar('pen')} so <b>Y</b>.</p>
<div class="map">
<div><b>C</b><span>Every visit: either X (butterfly house, if raining) or Y (ice cream) → condition for X fails (not raining) → so Y. {tick()} Same shape.</span></div>
<div><b>A</b><span>If build → more pupils. Can’t build → no more pupils. A single “if”, no either/or. {cross()}</span></div>
<div><b>B</b><span>If hires → can open. Open → must have hired. Backwards “if”. {cross()}</span></div>
<div><b>D</b><span>If illegal sales → spike. No spike → crackdown working. {cross()}</span></div>
<div><b>E</b><span>Armchair or side table → armchair is precious → side table goes. A preference, not a failed condition. {cross()}</span></div>
</div>
{note('Two parts to match: a rule that gives one of two outcomes, then “not this one, so that one”.', 'tip')}"""),

dict(n=7, orig=11, answer='D', type='Draw a conclusion',
     passage=[('counter', 'It is widely claimed that ancient stone circles were designed as astronomical observatories – that the stones were laid out to create sightlines to various celestial objects.'),
              ('ctx', 'While it seems clear that solar and lunar alignments were important in the layout of many circles,'),
              ('ic', 'there are problems when it comes to the stars.'),
              ('prem', 'Many stones are missing or have toppled over and it is extremely difficult to fix their original position. Further, the position of the stars in relation to each other is constantly changing.'),
              ('ctx', 'Using the laws of physics, we can recreate a map of the heavens for any period in the past.'),
              ('prem', 'But to draw conclusions about the orientation of any sightline, we have to know exactly when the stones were erected. Unfortunately, none of the dating methods used, including radiocarbon dating, is accurate enough for that. Finally, there are hundreds of combinations of stones at any site that produce sightlines.')],
     stem='Which one of the following can be drawn as a conclusion from the above passage?',
     options={'A': 'The builders of the stone circles knew less about the stars than modern humans.',
              'B': 'Better dating methods would let us determine the importance of sightlines.',
              'C': 'Ancient astronomical observations made using stone circles were inaccurate.',
              'D': 'It is unclear whether the stars were important in the layout of stone circles.',
              'E': 'The sun and moon were more important to ancient humans than the stars.'},
     right='Three problems (stones moved, dates too vague, too many possible sightlines) mean we can’t tell if star sightlines were planned. So it is unclear.',
     why={'A': 'The builders’ knowledge is never compared with ours.',
          'B': 'Better dating fixes only one problem. Missing stones and hundreds of sightlines remain.',
          'C': 'The passage says <b>we</b> can’t judge the sightlines, not that the builders got them wrong.',
          'E': 'Sun and moon mattered, but the passage doesn’t say stars mattered less. It says we can’t tell.'},
     gap='Match the strength of the passage: “there are problems” leads to “unclear”, not to “no”.'),

dict(n=8, orig=15, answer='C', type='Main conclusion',
     passage=[('ctx', 'A cataract is a clouding of the lens inside the eye, which results in decreased vision and eventually blindness.'),
              ('evid', 'Approximately half of all cases of blindness globally are cataract-related. Cataracts often lead to social exclusion, unemployment, depression and lower life expectancy.'),
              ('conc', 'Treatment by surgical replacement of the affected lens offers great value for the immense benefits it brings not only to the individual but also to society as a whole.'),
              ('evid', 'Cataract surgery is usually quite quick, does not require large, big-budget equipment or an overnight stay in hospital, and has a more than 90 per cent success rate.'),
              ('ic', 'This medical intervention is relatively inexpensive and straightforward if the necessary infrastructure and expertise are in place.')],
     stem='Which one of the following best expresses the main conclusion of the above argument?',
     options={'A': 'Approximately half of all cases of blindness globally are cataract-related.',
              'B': 'Cataracts often lead to social exclusion, unemployment, depression and lower life expectancy.',
              'C': 'Surgical cataract treatment offers great value for the immense benefits it brings not only to the individual but also to society as a whole.',
              'D': 'Cataract surgery is usually quite quick, does not require large, big-budget equipment or an overnight stay in hospital, and has a more than 90 per cent success rate.',
              'E': 'Cataract surgery is relatively inexpensive and straightforward if the necessary infrastructure and expertise are in place.'},
     right='“Great value” is the claim. The harm of cataracts shows the benefits; the quick, cheap surgery shows the low cost.',
     why={'A': 'Evidence of how big the problem is.',
          'B': 'Evidence of the harm cataracts cause, backing up the “immense benefits”.',
          'D': 'Evidence about the surgery, backing up the low cost.',
          'E': 'Sums up the surgery evidence (cheap, simple). A step towards “great value”, not the end point.'},
     gap='“Great value” has two halves: big benefits and low cost. Every other sentence supplies one half.'),

dict(n=9, orig=16, answer='B', type='Draw a conclusion',
     passage=[('ctx', 'Stora Karlsö is a Swedish island that is now set aside for wildlife conservation and is uninhabited by people except for the presence of ‘day-trippers’, who visit for only a few hours at a time. The population of murre seabirds there declined in the past because of people hunting them and collecting their eggs, but started to recover once these activities were banned.'),
              ('evid', 'During one recent summer, Stora Karlsö was closed to the tourists, and scientists monitoring the island made a surprising discovery. The percentage of eggs hatched by the murres dropped by 26% as dozens more white-tailed eagles flocked to the island.'),
              ('prem', 'It turns out that the eagles were encouraged by the lack of human visitors, while the murres were scared away from their nests by the influx of the larger birds.')],
     stem='Which one of the following can be drawn as a conclusion from the above passage?',
     options={'A': 'Focusing the efforts of a nature reserve on one particular species is not always an effective conservation strategy.',
              'B': 'The presence of people has a beneficial effect on wildlife species’ populations in some cases.',
              'C': 'Some kinds of bird species are less of a conservation priority than others.',
              'D': 'Limiting certain kinds of human activity is the fastest approach to increasing the population of a wildlife species.',
              'E': 'It is not always possible to conserve every species in some kinds of ecosystems.'},
     right='With no visitors, eagles moved in and murre hatching fell 26%. So here, having people around helped the murres: a benefit “in some cases”.',
     why={'A': 'The reserve is never said to focus on one species.',
          'C': 'Nothing ranks species by priority.',
          'D': '“Fastest” is never compared, and here limiting visitors made things worse.',
          'E': 'Too strong. With day-trippers back, both birds seem fine, so nothing shows it is impossible.'},
     gap='One example can support a modest “in some cases” conclusion, but nothing stronger.'),

dict(n=10, orig=17, answer='E', type='Flaw',
     passage=[('ctx', 'Calling a colleague ‘immature’ is not unlawful if they are behaving in a genuinely childish manner, a tribunal has ruled.'),
              ('evid', 'In a recent case an employee sued the director of the company where he worked for age discrimination. However, the director successfully argued that her calling the employee ‘immature’ was prompted by his abrasive manner and inability to lead a team, rather than his relatively young age. The tribunal dismissed the claims of discrimination,'),
              ('conc', 'so directors of companies should not be overly concerned about the legality of accusing their employees of being immature.')],
     stem='Which one of the following best illustrates the flaw in the above argument?',
     options={'A': 'An abrasive manner and inability to lead a team may be an indicator of immaturity.',
              'B': 'The fact that a tribunal has dismissed a case does not mean that the company in question acted ethically.',
              'C': 'The tribunal may have examined the character of the director rather than what had actually happened.',
              'D': 'Whether or not something is lawful may not be the only concern that directors might have.',
              'E': 'The fact that one case has been dismissed does not mean that all future cases will be dismissed.'},
     right='One case, decided on its own facts, is stretched to every accusation of immaturity. Next time the remark might really be about age.',
     why={'A': 'This backs the director’s side of the case. It isn’t a flaw in the argument.',
          'B': 'The conclusion is only about legality, not ethics.',
          'C': 'Guesswork about the tribunal. The real gap is going from one case to all cases.',
          'D': 'The conclusion is only about legality, so other concerns don’t touch it.'},
     gap='The ruling had a condition (“if… genuinely childish”). The conclusion quietly drops it.'),

dict(n=11, orig=21, answer='C', type='Strengthen',
     passage=[('ctx', 'In recent years, the production and visibility of colourised and ‘restored’ historical photographs has grown exponentially, owing to both social media and the introduction of user-friendly colourisation software. But the expansion of the technical capacity and popular appetite to alter historical photography has not been matched by sufficient debate about the assumptions and consequences of this practice.'),
              ('prem', 'Colourisers do not address photographs as physical artefacts with unique histories of creation and reception: they treat original photos as ‘windows’ onto the past that can be ‘improved’ for viewers. But a photograph is never just a neutral representation of the past. Every photograph carries with it a complicated history of who took it, who looked at it, how it was shaped by the technology behind it, and what all this means for questions of representation, experience, and history.'),
              ('conc', 'Colourisation blocks out this rich repository of historical meaning, substituting a fleeting jolt of novelty for deeper understanding of the image.')],
     stem='Which one of the following, if true, most strengthens the above argument?',
     options={'A': 'Artificial intelligence is now being used to colourise photographs automatically.',
              'B': 'Colourisation techniques are almost as old as photography itself.',
              'C': 'Some photographers of the past chose to use black and white film instead of colour.',
              'D': 'Some universities no longer teach courses on the history of photography.',
              'E': 'Colourisers rarely have academic experience of studying history.'},
     right='If black and white was a deliberate choice, it is part of the photo’s history of creation. Colouring it in wipes that choice out, just as the argument says.',
     why={'A': 'Only says how colouring is done, not that it hides meaning.',
          'B': 'Makes colouring part of photography’s own history. If anything this weakens.',
          'D': 'About university courses, not about what colourisation does to a photo.',
          'E': 'An attack on who does it. The argument is about what colourisation does, whoever does it.'},
     gap='Strengthen the last sentence: find the option showing that the lack of colour itself carries meaning.'),

dict(n=12, orig=22, answer='C', type='Principle',
     passage=[('ctx', 'There has been discontent amongst students following the decision of a number of UK universities to use automated marking software to assess students’ written work. Of course, there are ethical issues surrounding the use of such software.'),
              ('prem', 'But a simple reason why the students are right to feel aggrieved is that it is not clear that they were told, when embarking on the course, that this would happen. You have every right to complain about something which affects you if you have not previously been informed, consulted, or given your consent.'),
              ('conc', 'The students are therefore justified in their complaints.')],
     stem='Which one of the following illustrates the principle used in the above argument?',
     options={'A': 'A customer has every right to demand a refund rather than accept an alternative product offered by a supplier.',
              'B': 'Someone selling their house ought to inform the buyer if they cannot guarantee the property will be left satisfactorily clean.',
              'C': 'A patient who has been prescribed a medication that has unpleasant side effects is entitled to complain if they were not warned of this possibility.',
              'D': 'A consumer who is offered a no-returns purchase ought to be fully informed about the implications of this transaction.',
              'E': 'A citizen who is arrested for a suspected crime has every right to complain if they believe the police used unnecessary force.'},
     right='The side effects affect the patient, and nobody warned them. So, like the students, they are entitled to complain.',
     why={'A': 'A right to a refund, with nothing about not being told in advance.',
          'B': 'A duty to inform beforehand, not a right to complain after not being told.',
          'D': 'Again a duty to inform, not a right to complain.',
          'E': 'A right to complain, but about force, not about being kept in the dark.'},
     working_title='Working: write the principle first',
     working=f"""<p class="skel">Marking software affects students {ar('pen')} they weren’t clearly told {ar('pen')} so they may complain.<br>
So the principle: <b>if something affects you and you weren’t informed, consulted or asked, you have the right to complain</b>.</p>
<div class="map">
<div><b>C</b><span>Side effects affect the patient → not warned → entitled to complain. {tick()} Same principle.</span></div>
<div><b>A</b><span>Can demand a refund: no “not informed” part. {cross()}</span></div>
<div><b>B</b><span>Seller ought to inform: a duty to tell, not a right to complain. {cross()}</span></div>
<div><b>D</b><span>Consumer ought to be informed: a duty to tell again. {cross()}</span></div>
<div><b>E</b><span>Can complain about force: right to complain, wrong trigger. {cross()}</span></div>
</div>
{note('Both halves must match: the trigger (not informed) and the result (a right to complain).', 'tip')}"""),

dict(n=13, orig=23, answer='C', type='Parallel reasoning',
     passage=[('prem', 'The chef will not go ahead with her cooking class tomorrow unless at least fifteen people sign up for it by 5 pm today.'),
              ('evid', 'It is now 4 pm and twenty people have already registered,'),
              ('conc', 'so she will be teaching the class tomorrow.')],
     stem='Which one of the following most closely parallels the reasoning used in the above argument?',
     options={'A': 'Unless enough rain fell during the summer months to water the crops, they would all have died out by July. It is now August and the crops are still surviving, so there was adequate rainfall earlier in the year.',
              'B': 'The architect’s plan cannot be approved by the local authorities unless it meets all of the relevant regulations. The plan will be rejected since the architect has disregarded two of the rules.',
              'C': 'Unless more public transport options are made available, traffic congestion in town will never improve. The mayor has announced that new bus lines will be introduced next month, so traffic will start to ease up after that.',
              'D': 'The competition is not conducted fairly unless all of the judges are completely impartial. One of the judges is biased in favour of one of the competitors because they are from the same country, so that competitor is more likely to win.',
              'E': 'Unless the data has been analysed accurately, it cannot be included in the final report. The report was handed in today and did not contain the data, so mistakes must have been made with its analysis.'},
     right='Same flaw: Y is needed for X, Y is met, so X will happen. Fifteen sign-ups and more transport are needed, not enough on their own.',
     why={'A': 'Valid: the crops survived, so the needed rain must have fallen. Reasons from the result back.',
          'B': 'Valid: the needed condition is missing, so no approval.',
          'D': 'Condition missing, then a new conclusion about who wins. Different shape.',
          'E': 'The data is missing, so it must be inaccurate. A different flaw: it could be missing for another reason.'},
     working_title='Working: strip it to a skeleton',
     working=f"""<p class="skel">Original: not <b>X</b> (class) unless <b>Y</b> (15 sign-ups), so Y is <b>needed</b> for X {ar('pen')} Y is met (20) {ar('pen')} so X. <i>Flaw: needed ≠ enough.</i></p>
<div class="map">
<div><b>C</b><span>Not X (traffic improves) unless Y (more transport) → Y is coming (bus lines) → so X. {tick()} Same flaw.</span></div>
<div><b>A</b><span>Without Y (rain) not X (survive) → X happened → so Y. Valid. {cross()}</span></div>
<div><b>B</b><span>Not X (approved) unless Y (rules met) → not Y → so not X. Valid. {cross()}</span></div>
<div><b>D</b><span>Not X (fair) unless Y (impartial) → not Y → “more likely to win”. New conclusion. {cross()}</span></div>
<div><b>E</b><span>Not X (included) unless Y (accurate) → not X → so not Y. Different flaw. {cross()}</span></div>
</div>
{note('“X unless Y” makes Y a must-have. Having Y does not guarantee X: the chef could still fall ill.', 'trap')}"""),

dict(n=14, orig=27, answer='B', type='Flaw',
     passage=[('ctx', 'When hiring new employees for senior positions, many companies focus their search on applicants who already have some previous experience working in a similar job.'),
              ('prem', 'This happens even though simply having had another job does not automatically mean that that person performed well in that role. Moreover, some people got their jobs because they have personal connections with the employers, not because they were the most competent or suitable candidate. And even if an applicant is highly qualified and did excel at another job, the different work environments at different organisations often make it challenging for them to apply their previous work experience to a new role.'),
              ('conc', 'This shows that companies that automatically reject inexperienced applicants are taking the wrong approach.')],
     stem='Which one of the following best illustrates the flaw in the above argument?',
     options={'A': 'Companies may be trying to save time by focusing on candidates who have previous work experience.',
              'B': 'It may be that good performance, although not guaranteed by previous experience, is impossible without it.',
              'C': 'Just because someone got a job through personal connections does not mean that they are unqualified for it.',
              'D': 'Inexperienced applicants may be able to access internships and other training opportunities.',
              'E': 'Just because companies focus on applicants with previous work experience does not mean they do not consider other qualifications.'},
     right='Every reason shows experience is not <b>enough</b> for good performance. It may still be <b>needed</b>, and then rejecting the inexperienced makes sense.',
     why={'A': 'A possible motive for the companies. It doesn’t point to the gap in the reasoning.',
          'C': 'The argument never says such people are unqualified, only maybe not the most competent.',
          'D': 'Training elsewhere is beside the point. It doesn’t touch the reasoning.',
          'E': 'The conclusion is about firms that automatically reject the inexperienced. Other qualifications don’t change that.'},
     gap='“Does not guarantee” (not enough) is different from “not needed”. Classic sufficient vs necessary mix-up.'),

dict(n=15, orig=28, answer='C', type='Main conclusion',
     passage=[('ctx', 'According to legend, the ancient cities of both Thebes and Troy were founded, not at the summit of a hill, nor the junction of two waterways, but where a cow decided to lie down.'),
              ('counter', 'The practice of allowing cows to choose where a city should be built would seem to be arbitrary and bizarre;'),
              ('conc', 'a little reflection tells us that it is perhaps not so strange after all.'),
              ('prem', 'Since a city means a sizeable population,'),
              ('ic', 'there must be plentiful sources of meat, milk, leather and cheese, not to mention strong draught animals for ploughing fields and pulling carts.'),
              ('prem', 'If a cow is taken enough by the amenities of a place to feel able to lie down, then it is worth paying attention.')],
     stem='Which one of the following best expresses the main conclusion of the above argument?',
     options={'A': 'According to legend, both Thebes and Troy were founded where a cow chose to lie down.',
              'B': 'The practice of allowing cows to choose where a city should be built would seem to be arbitrary and bizarre.',
              'C': 'A little reflection tells us that it is not so strange to allow a cow to choose where to build a city.',
              'D': 'Cities demand plentiful sources of meat, milk, leather, cheese, as well as strong draught animals.',
              'E': 'If a cow is taken enough by the amenities of a place to feel able to lie down, then it is worth paying attention.'},
     right='The author answers the “bizarre” view: it is not so strange. The cattle needs of a city and the happy cow are the reasons.',
     why={'A': 'Background: the legend.',
          'B': 'The opposing view, which the author rejects.',
          'D': 'A reason: cities need lots of cattle products.',
          'E': 'A reason: a contented cow is a good sign about the place.'},
     gap='“Would seem… ; … not so strange after all”: the author’s reply to the first view is the conclusion.'),

dict(n=16, orig=29, answer='E', type='Draw a conclusion',
     passage=[('ctx', 'Why is it that disagreements have a tendency to become so heated?'),
              ('ic', 'The problem arises from the fact that people who think differently from you, on any topic, are perceived subconsciously as a threat. Not a physical threat, necessarily, but a threat to your reputation.'),
              ('ctx', 'Why is this?'),
              ('prem', 'Because if someone who thinks differently from you is right (or merely perceived by others to be right), it typically implies that you are wrong. And being wrong (or seen to be wrong) is something that we all fear. Our worry is that it will damage our credibility as someone others should listen to or trust. And trust, naturally, is an extremely valuable commodity for social creatures such as ourselves.')],
     stem='Which one of the following can be drawn as a conclusion from the above passage?',
     options={'A': 'If two people think differently, they cannot both be right.',
              'B': 'In order to be effective in a debate, someone must earn the trust of those around them.',
              'C': 'We fear reputational threats just as much as we do physical threats.',
              'D': 'If someone thinks the same way as you, they will not perceive you as a threat.',
              'E': 'If we did not fear being wrong, disagreements would be less likely to get heated.'},
     right='Heat comes from feeling threatened, and the threat comes from fearing being wrong. Remove that fear and the chain breaks, so less heat.',
     why={'A': 'Too strong. It only “typically implies” you are wrong.',
          'B': 'Being effective in debate is never discussed.',
          'C': '“Just as much” is never claimed. Physical threats are barely mentioned.',
          'D': 'Reverses it: those who differ are seen as a threat, but agreeing doesn’t guarantee you aren’t.'},
     gap='Follow the chain: heated ← threat ← fear of being wrong. A good conclusion can take out a link.'),

dict(n=17, orig=33, answer='B', type='Strengthen',
     passage=[('ctx', 'Over the past few decades, many companies have developed sustainability initiatives designed to improve their environmental performance across areas ranging from water usage to the recyclability of products. At the same time, there has been an increase in award programmes designed to recognise achievement in such initiatives.'),
              ('counter', 'Unsurprisingly, these awards attract criticism and scepticism, especially since it is often the companies that nominate themselves to receive them. While some of the awards may not represent meaningful progress,'),
              ('conc', 'we shouldn’t dismiss or reject them entirely.'),
              ('prem', 'Many are awarded by judging panels that include representatives from environmental organisations. Moreover, the positive publicity and other benefits that come with winning awards help gain support for a company’s sustainability efforts amongst the senior decision-makers at that company.')],
     stem='Which one of the following, if true, most strengthens the above argument?',
     options={'A': 'Participation in award programmes can be an enjoyable experience for company employees.',
              'B': 'The award programmes provide a way for companies to learn about environmental management advancements within their own industries.',
              'C': 'Members of the public lack the knowledge needed to assess claims about sustainability-related achievements.',
              'D': 'Companies that have been previous award winners go on to participate on judging panels for the award programmes.',
              'E': 'The awards help companies that win them reduce the amount of money they spend on advertising their products.'},
     right='Another real environmental benefit: companies learn about new ways to manage their impact. One more reason not to dismiss the awards.',
     why={'A': 'Fun for staff does nothing for the environment.',
          'C': 'Not one of the reasons given. If anything, a public that can’t check claims is easily misled by awards.',
          'D': 'Past winners judging makes panels less independent: this weakens.',
          'E': 'Saving on adverts helps the company’s budget, not its sustainability.'},
     gap='The argument values awards for helping sustainability. Strengthen it with another sustainability benefit.'),

dict(n=18, orig=34, answer='D', type='Assumption',
     passage=[('ctx', 'A common method of punishing minor offences such as speeding or dropping litter is to impose monetary fines on the offender. These fines also aim to deter people from breaking the law in the first place.'),
              ('conc', 'However, it is evident that fines are an unfair method of deterring and punishing people.'),
              ('prem', 'If caught, wealthy people will be able to pay off fines with little to no trouble, and are therefore unlikely to feel deterred by the punishment. On the other hand, poorer people are more likely to have to borrow money to pay the fine, or even face further punishment such as jail time for not paying the original fine, which are disproportionately negative outcomes for committing a minor offence.')],
     stem='Which one of the following is an underlying assumption of the above argument?',
     options={'A': 'There are other methods of punishment that are fairer than imposing fines.',
              'B': 'People are aware of the punishments they will face if they are caught breaking the law.',
              'C': 'Poorer people are more likely to get caught committing minor offences than wealthier people.',
              'D': 'An offender’s wealth does not affect the amount they are fined.',
              'E': 'People are unlikely to repeat an offence if they are punished for it the first time.'},
     right='The rich shrug fines off and the poor struggle only if everyone is fined the same amount. Fines scaled to wealth would hit both alike.',
     why={'A': 'Not needed. The argument only says fines are unfair, not that something better exists.',
          'B': 'Not needed. Even if people don’t know the fines in advance, paying still hits the poor harder.',
          'C': 'Not needed. The unfairness is in paying the fine, not in who gets caught.',
          'E': 'Repeat offending is never discussed.'},
     gap='Negation test: if fines DO depend on wealth, the rich feel them too and the argument falls.'),

dict(n=19, orig=35, answer='D', type='Flaw',
     passage=[('ctx', 'So far, most attention given to reproductive health has focused on women’s fertility. Therefore, it’s a welcome development that researchers are showing more concern about what impacts the fertility of men. Factors already known to affect sperm production range from the ageing process to poor diets and fitness levels. Now, increasing attention is being paid to workplace chemical exposure as another potential factor.'),
              ('evid', 'For example, some studies have found that the longer men work in certain factory jobs, the lower the quality of their sperm production.'),
              ('conc', 'This finding is enough to identify factory chemical exposure as a priority risk and begin changing factory working conditions to reduce it.')],
     stem='Which one of the following best illustrates the flaw in the above argument?',
     options={'A': 'Fertility problems may be more common amongst women than they are amongst men.',
              'B': 'Just because there are risks associated with workplace chemical exposure does not mean other risks to men’s fertility should be ignored.',
              'C': 'Lower quality sperm production may already be an issue by the time men start factory jobs.',
              'D': 'Just because lower quality sperm production is associated with more time in a job doesn’t mean it is caused by that job.',
              'E': 'Just because one risk to fertility is reduced doesn’t mean that someone’s reproductive health will actually be improved.'},
     right='A link is not proof of cause. Men who have worked longer are also older, and the passage itself names ageing as a known factor.',
     why={'A': 'Women’s fertility is background. It doesn’t affect the reasoning about men.',
          'B': 'The argument never says other risks should be ignored.',
          'C': 'The finding is that quality falls the longer men work, so a problem at the start doesn’t explain the trend.',
          'E': 'The argument only says reduce the risk. It never promises better health.'},
     gap='“The longer… the lower…” is a correlation. Look for something else that grows with time in the job.'),

dict(n=20, orig=39, answer='E', type='Parallel reasoning',
     passage=[('prem', 'For an earthquake to take place, there needs to be pressure generated between the Earth’s tectonic plates.'),
              ('evid', 'The pressure has increased along this fault line,'),
              ('conc', 'so we can expect an earthquake soon.')],
     stem='Which one of the following most closely parallels the reasoning used in the above argument?',
     options={'A': 'An increase in wages implies an increase in a company’s running costs. As wages have been frozen for a year, we can assume that it costs the same now to run the company as it did 12 months ago.',
              'B': 'To survive, coral reefs need clear water that lets sunlight through. This reef is thriving, so the water conditions must be ideal for it.',
              'C': 'If a cat is to live with humans successfully when it is fully grown, it must be socialised with them while still a kitten. This cat grew up in the wild, so it is unlikely to make a good pet.',
              'D': 'A sonic boom implies that an object has broken the sound barrier. The jet did not break the sound barrier, so cannot have created a sonic boom.',
              'E': 'A ship cannot be steered without a rudder. This vessel is equipped with one, so we should be able to change course.'},
     right='Same flaw: Y is needed for X, Y is present, so expect X. A rudder is needed to steer, but having one doesn’t guarantee you can.',
     why={'A': 'If X then Y; not X, so not Y. A different flaw (other costs could rise).',
          'B': 'Goes from the result (thriving) back to the condition. Reverse direction.',
          'C': 'The needed condition is missing, so probably not X. Valid.',
          'D': 'If X then Y; not Y, so not X. Valid.'},
     working_title='Working: strip it to a skeleton',
     working=f"""<p class="skel">Original: <b>Y</b> (pressure) is <b>needed</b> for <b>X</b> (earthquake) {ar('pen')} Y is present {ar('pen')} so expect X. <i>Flaw: needed ≠ enough.</i></p>
<div class="map">
<div><b>E</b><span>Y (rudder) needed for X (steering) → Y present → so X. {tick()} Same flaw.</span></div>
<div><b>A</b><span>If X (wage rise) then Y (cost rise) → not X → so not Y. Different flaw. {cross()}</span></div>
<div><b>B</b><span>Y (clear water) needed for X (survive) → X (thriving) → so Y. Starts from the result. {cross()}</span></div>
<div><b>C</b><span>Y (socialised) needed for X (good pet) → not Y (wild) → so probably not X. Valid. {cross()}</span></div>
<div><b>D</b><span>If X (boom) then Y (barrier broken) → not Y → so not X. Valid. {cross()}</span></div>
</div>
{note('This is the same pattern as Q13. Spot the must-have condition, then check the option says “we have it, so it will happen”.', 'tip')}"""),

dict(n=21, orig=40, answer='C', type='Principle',
     passage=[('counter', 'A political party in Freedonia has raised overblown concerns about freedom of speech, claiming that hate-speech laws are a form of censorship and undermine academic freedom. After all, these laws may prevent people from voicing their opinions in public, and academics may not be able to teach and write without interference.'),
              ('conc', 'However, the party has no leg to stand on in decrying these hate-speech laws:'),
              ('evid', 'they proposed a law that would ban Freedonian teachers from teaching negative perspectives on the history of the Freedonian empire.'),
              ('ic', 'This hypocrisy is very disappointing:'),
              ('prem', 'as the old saying goes, people in glass houses shouldn’t throw stones.')],
     stem='Which one of the following best illustrates the principle used in the above argument?',
     options={'A': 'Those who have only negative things to say should say nothing at all.',
              'B': 'Those who cheat in their university exams should automatically fail their degree.',
              'C': 'Those who are rude to their friends should not complain if their friends are rude in return.',
              'D': 'Teachers should be careful what they teach pupils, in case they upset their parents.',
              'E': 'Historical figures who did awful things should be scrutinised and criticised in public debate.'},
     right='“Glass houses”: if you do something yourself, you can’t complain when others do it. Rude people can’t complain about rudeness.',
     why={'A': 'Picks up the word “negative”, but it is about kindness, not hypocrisy.',
          'B': 'A punishment rule for cheats. No hypocrisy.',
          'D': 'Same topic (teaching), different idea.',
          'E': 'Same topic (history, criticism), but about scrutiny, not hypocrisy.'},
     working_title='Working: write the principle first',
     working=f"""<p class="skel">Party complains about limits on speech {ar('pen')} but wants to limit what teachers say {ar('pen')} so it can’t complain (glass houses).<br>
So the principle: <b>if you do something yourself, you can’t fairly object when others do the same</b>.</p>
<div class="map">
<div><b>C</b><span>Rude to friends → can’t complain when they are rude back. {tick()} Same principle.</span></div>
<div><b>A</b><span>Say nothing if only negative: about being kind. {cross()}</span></div>
<div><b>B</b><span>Cheats should fail: a punishment. {cross()}</span></div>
<div><b>D</b><span>Teachers should be careful: topic match only. {cross()}</span></div>
<div><b>E</b><span>Criticise historical figures: topic match only. {cross()}</span></div>
</div>
{note('Options D and E reuse the passage’s topics (teaching, history). Principle questions reward the same idea in a new setting.', 'trap')}"""),

dict(n=22, orig=41, answer='E', type='Draw a conclusion',
     passage=[('ctx', 'Most countries around the world only allow citizens to vote in elections when they are at least 18 years old.'),
              ('counter', 'Many oppose lowering this to 16, pointing out that at this age, people cannot even legally drive a car in most places.'),
              ('ic', 'However, voting is not like driving a car'),
              ('prem', '– it does not require impulse control or split-second decision-making, abilities which are not well developed during the teenage years. Voters are not presented with the candidates just seconds before they must make a choice. Rather, voters have time to deliberate and think about their decision, and this type of dispassionate reasoning matures, on average, in the mid-teens. This is the key factor that should determine who is allowed to vote. Moreover, many adults much older than 16 are not more knowledgeable about politics than your average 16-year-old, nor do they even deliberate all that much before casting their votes.')],
     stem='Which one of the following can be drawn as a conclusion from the above passage?',
     options={'A': 'The minimum age at which someone can legally vote should be the same as the minimum age for legal driving.',
              'B': 'The minimum ages to vote and to drive should be based on individual ability, not on age alone.',
              'C': 'Lowering the minimum age to vote to 16 would increase the number of people turning up to vote in elections.',
              'D': 'The minimum age to vote is influenced by the minimum age at which one can drive.',
              'E': 'The average 16-year-old is just as qualified to vote in an election as many older adults.'},
     right='The key factor (reasoning) matures by the mid-teens, and many older adults know and deliberate no more. So the average 16-year-old is as qualified as many of them.',
     why={'A': 'The passage argues voting is <b>not</b> like driving, so the ages need not match.',
          'B': 'The passage reasons about averages. Testing individuals, and driving rules, are never proposed.',
          'C': 'Turnout is never mentioned.',
          'D': 'Opponents compare the two, but nothing says the voting age is actually set by the driving age.'},
     gap='Put the “key factor” together with the “Moreover” point about older adults.'),

dict(n=23, orig=45, answer='A', type='Weaken',
     passage=[('ctx', 'Online courses are becoming more common in colleges and universities, which is a worrying trend given the data that we have on how effective they are.'),
              ('evid', 'Studies have found that students taking online courses are much more likely to multitask during their lessons compared to students in traditional in-person classes.'),
              ('prem', 'After all, with no teacher present in the room to deter you from checking your emails, listening to music, and scrolling through social media, it is much easier to be tempted by these distractions.'),
              ('evid', 'This is a problem because we also have plenty of data to show that multitasking during educational activities significantly reduces how much you learn. Indeed, students taking online courses, on average, end up performing worse in assessments and are more likely to drop out than students taking in-person courses.'),
              ('conc', 'Clearly, online courses are detrimental to learning compared to in-person ones.')],
     stem='Which one of the following, if true, most weakens the above argument?',
     options={'A': 'Online courses tend to attract students who are also working part time or have childcare responsibilities.',
              'B': 'Highly focused students attending online courses still perform well in assessments.',
              'C': 'Some students can only attend online courses because they have difficulty moving around.',
              'D': 'There are also distractions during in-person classes, such as the presence of classmates.',
              'E': 'Older students tend to be more motivated than younger students.'},
     right='Students with jobs or children have less time, which could explain the worse marks and drop-outs whatever the course format. Another cause.',
     why={'B': 'Focused students doing well fits the argument: the problem is distraction.',
          'C': 'About who can get to courses, not how well online courses teach.',
          'D': 'The studies already found online students multitask much more, so some in-class distraction doesn’t change that.',
          'E': 'Age is never linked to online courses.'},
     gap='For “X causes worse results”, look for a different kind of person choosing X.'),

dict(n=24, orig=47, answer='E', type='Assumption',
     passage=[('ctx', 'In the USA, interest paid on a home loan is tax-deductible (meaning it can be deducted from your taxable income, reducing the tax you pay to the government). This tax break is known as mortgage interest deduction,'),
              ('conc', 'and it should be abolished.'),
              ('prem', 'After all, the poorest Americans generally rent their homes rather than owning them, and rent cannot be deducted from taxes. And certain technicalities related to how taxes are filed often prevent poorer homeowners from receiving the deduction.'),
              ('ic', 'This means that the poorest Americans benefit the least from mortgage interest deduction. The people who benefit the most are the richest,'),
              ('prem', 'since they own the most expensive houses and have the largest tax bills, and often employ accountants to file their taxes for maximum deductions. The American government could more than double rental assistance payments to poorer Americans with the money lost as a result of this tax break.')],
     stem='Which one of the following is an underlying assumption of the above argument?',
     options={'A': 'Government money should not be spent subsidising private household consumption choices.',
              'B': 'The financial benefits you receive from the government should not depend on whether you are rich or poor.',
              'C': 'Money raised by taxing the rich should be used to support the poor.',
              'D': 'There are no low-cost accounting services that poorer Americans can access.',
              'E': 'The government should not offer tax breaks that benefit the richest most and the poorest least.'},
     right='The reasons only show the break helps the rich most and the poor least. To get to “abolish it”, you need the rule that such tax breaks should not exist.',
     why={'A': 'Too broad. The argument wants more rental assistance, which is itself a subsidy for housing.',
          'B': 'Too strong. The argument wants extra help just for poorer people, so it accepts benefits that depend on wealth.',
          'C': 'Not needed. Abolishing the break is justified by its unfairness, whatever the money is then used for.',
          'D': 'Not needed. The technicalities and the renters’ point stand without it.'},
     gap='The missing rule bridges “this is unequal” to “so get rid of it”.'),

dict(n=25, orig=49, answer='B', type='Parallel reasoning',
     passage=[('prem', 'To win business investment, you need a good product and a well-developed business plan.'),
              ('evid', 'Your product is brilliant, but you haven’t spent enough time on the plan.'),
              ('conc', 'So it’s unlikely you’ll get funding.')],
     stem='Which one of the following most closely parallels the reasoning used in the above argument?',
     options={'A': 'For the school to approve their proposal for meat-free lunches, the students must develop a menu and win support from their peers. The student body has approved their new menu in a poll, so it’s unlikely the school will continue to serve meat.',
              'B': 'The only way their team will be disqualified is if they miss a match and fail to notify the tournament director at least three hours before the start of play. They couldn’t attend the first match but told the director in plenty of time, meaning they won’t be disqualified.',
              'C': 'The new hotel manager must be fluent in Mandarin and Korean. This candidate speaks both, meaning the hotel won’t need to interview anyone else.',
              'D': 'To earn a distinction in music, you must perform in public concerts or write your own music composition. You don’t have time for the concerts or the composition, so it’s unlikely you’ll earn a distinction.',
              'E': 'If they want to take a holiday that is affordable and unique, the friends can volunteer on a farm or at a nature reserve. The farm only hosts volunteers for the weekend, so they probably won’t go there.'},
     right='Same shape: X needs both A and B. A is there (missed a match), B isn’t (they told the director), so no X.',
     why={'A': 'Both conditions are met, so it concludes X will happen. Treats needed as enough.',
          'C': 'Both conditions are met, so the job is settled. Needed treated as enough.',
          'D': 'Needs A <b>or</b> B, and neither is met. A different shape.',
          'E': 'Two options, one looks unsuitable, so they won’t pick it. No “need both” rule.'},
     working_title='Working: strip it to a skeleton',
     working=f"""<p class="skel">Original: <b>X</b> (funding) needs <b>A and B</b> (product and plan) {ar('pen')} A yes, B no {ar('pen')} so (probably) not X.</p>
<div class="map">
<div><b>B</b><span>X (disqualified) needs A (miss a match) and B (fail to notify) → A yes, B no (told in time) → so not X. {tick()} Same shape.</span></div>
<div><b>A</b><span>X (approval) needs A (menu) and B (support) → both met → so X. Needed treated as enough. {cross()}</span></div>
<div><b>C</b><span>X (job) needs A (Mandarin) and B (Korean) → both met → so X. Needed treated as enough. {cross()}</span></div>
<div><b>D</b><span>X needs A <b>or</b> B → neither → so not X. “Or”, not “and”. {cross()}</span></div>
<div><b>E</b><span>Farm or reserve → farm is weekends only → not the farm. No two-part condition. {cross()}</span></div>
</div>
{note('B is about a bad outcome (disqualification), not a good one. Ignore the topic and mood; match the logic.', 'tip')}"""),
]
